dashboardRouter.post("/auth/accept-manager-invite", rateLimitByBodyField("token", 10, 15 * 6e4, "accept-manager-invite"), async (req, res) => {
  const { token, password } = req.body;
  if (!token?.trim() || !password) {
    res.status(400).json({ message: "Token et mot de passe requis" });
    return;
  }
  if (password.length < 8) {
    res.status(400).json({ message: "Le mot de passe doit contenir au moins 8 caract\xE8res" });
    return;
  }
  try {
    const tokenHash = hashSecureToken(token.trim());
    const invite = await getManagerInviteByTokenHash(tokenHash);
    if (!invite) {
      res.status(400).json({ message: "Invitation invalide ou expir\xE9e" });
      return;
    }
    if (invite.expiresAt.getTime() < Date.now()) {
      res.status(400).json({ message: "Invitation expir\xE9e" });
      return;
    }
    if (await getManagerByEmail(invite.email)) {
      res.status(409).json({ message: "Cet e-mail est d\xE9j\xE0 utilis\xE9" });
      return;
    }
    const passwordHash = await bcryptjs_default.hash(password, 10);
    const created = await createManager(`mgr-${randomUUID11()}`, invite.email, passwordHash, invite.name, invite.companyId, "manager");
    await markManagerInviteAccepted(invite.id);
    logSecurityEvent({
      action: "manager.invite.accepted",
      actorType: "manager",
      actorId: created.id,
      companyId: created.companyId,
      metadata: { email: created.email },
      req
    });
    const accessToken = signManagerToken(created.id, created.email, created.companyId, created.role);
    setManagerAuthCookie(res, accessToken);
    res.status(201).json({
      ok: true,
      manager: {
        id: created.id,
        email: created.email,
        name: created.name,
        companyId: created.companyId,
        role: created.role
      }
    });
  } catch (err) {
    if (isPgUniqueViolation(err)) {
      res.status(409).json({ message: "Cet e-mail est d\xE9j\xE0 utilis\xE9" });
      return;
    }
    console.error("[dashboard] accept invite error", err);
    res.status(500).json({ message: "Erreur serveur" });
  }
});
dashboardRouter.post("/auth/manager-forgot-password", rateLimitByBodyField("email", 5, 60 * 6e4, "manager-forgot-password"), async (req, res) => {
  const email3 = String(req.body.email ?? "").trim().toLowerCase();
  if (!email3 || !isValidManagerEmail(email3)) {
    res.status(400).json({ message: "Adresse e-mail invalide" });
    return;
  }
  try {
    const row = await getManagerByEmail(email3);
    if (row) {
      const { token, tokenHash } = generateSecureToken();
      await createManagerPasswordReset({
        id: `mreset-${randomUUID11()}`,
        managerId: row.id,
        tokenHash,
        expiresAt: new Date(Date.now() + 36e5)
      });
      await sendManagerPasswordResetEmail({ to: row.email, name: row.name, token });
    }
    res.json({ ok: true, message: "Si un compte existe, un e-mail de r\xE9initialisation a \xE9t\xE9 envoy\xE9." });
  } catch (err) {
    console.error("[dashboard] forgot password error", err);
    res.status(500).json({ message: "Erreur serveur" });
  }
});
dashboardRouter.post("/auth/manager-reset-password", rateLimitByBodyField("token", 10, 15 * 6e4, "manager-reset-password"), async (req, res) => {
  const { token, password } = req.body;
  if (!token?.trim() || !password) {
    res.status(400).json({ message: "Token et mot de passe requis" });
    return;
  }
  if (password.length < 8) {
    res.status(400).json({ message: "Le mot de passe doit contenir au moins 8 caract\xE8res" });
    return;
  }
  try {
    const tokenHash = hashSecureToken(token.trim());
    const reset = await getManagerPasswordResetByTokenHash(tokenHash);
    if (!reset || reset.expiresAt.getTime() < Date.now()) {
      res.status(400).json({ message: "Lien de r\xE9initialisation invalide ou expir\xE9" });
      return;
    }
    const passwordHash = await bcryptjs_default.hash(password, 10);
    const updated = await updateManager(reset.managerId, { passwordHash });
    if (!updated) {
      res.status(404).json({ message: "Compte introuvable" });
      return;
    }
    await markManagerPasswordResetUsed(reset.id);
    logSecurityEvent({
      action: "manager.password.reset",
      actorType: "manager",
      actorId: updated.id,
      companyId: updated.companyId,
      req
    });
    res.json({ ok: true });
  } catch (err) {
    console.error("[dashboard] reset password error", err);
    res.status(500).json({ message: "Erreur serveur" });
  }
});
dashboardRouter.patch("/dashboard/managers/:id", requireAdmin, async (req, res) => {
  const { manager } = req;
  const { id } = req.params;
  const { name: name2, email: email3, password, role } = req.body;
  try {
    const current = await getManagerById(String(id));
    if (!current || current.companyId !== manager.companyId) {
      res.status(404).json({ message: "Gestionnaire introuvable" });
      return;
    }
    if (role === "manager" && current.role === "admin") {
      const admins = await countAdmins(manager.companyId);
      if (admins <= 1) {
        res.status(400).json({ message: "Impossible de retirer le dernier administrateur." });
        return;
      }
    }
    const update = {};
    if (name2?.trim())
      update.name = name2.trim();
    if (email3?.trim()) {
      const normalizedEmail = email3.trim().toLowerCase();
      if (!isValidManagerEmail(normalizedEmail)) {
        res.status(400).json({ message: "Adresse e-mail invalide" });
        return;
      }
      const owner = await getManagerByEmail(normalizedEmail);
      if (owner && owner.id !== current.id) {
        res.status(409).json({ message: "Cet e-mail est d\xE9j\xE0 utilis\xE9" });
        return;
      }
      update.email = normalizedEmail;
    }
    if (password) {
      if (password.length < 8) {
        res.status(400).json({ message: "Le mot de passe doit contenir au moins 8 caract\xE8res" });
        return;
      }
      update.passwordHash = await bcryptjs_default.hash(password, 10);
    }
    if (role === "admin" || role === "manager")
      update.role = role;
    const row = await updateManager(String(id), update);
    if (!row) {
      res.status(404).json({ message: "Gestionnaire introuvable" });
      return;
    }
    if (update.role && update.role !== current.role) {
      logSecurityEvent({
        action: "manager.role.changed",
        actorType: "manager",
        actorId: manager.sub,
        companyId: manager.companyId,
        metadata: { targetId: row.id, from: current.role, to: row.role },
        req
      });
    }
    res.json({
      ok: true,
      manager: { id: row.id, name: row.name, email: row.email, role: row.role }
    });
  } catch (err) {
    if (isPgUniqueViolation(err)) {
      res.status(409).json({ message: "Cet e-mail est d\xE9j\xE0 utilis\xE9" });
      return;
    }
    console.error("[dashboard] update manager error", err);
    res.status(500).json({ message: "Erreur serveur" });
  }
});
dashboardRouter.delete("/dashboard/managers/:id", requireAdmin, async (req, res) => {
  const { manager } = req;
  const targetId = String(req.params.id);
  if (targetId === manager.sub) {
    res.status(400).json({ message: "Vous ne pouvez pas supprimer votre propre compte." });
    return;
  }
  try {
    const current = await getManagerById(targetId);
    if (!current || current.companyId !== manager.companyId) {
      res.status(404).json({ message: "Gestionnaire introuvable" });
      return;
    }
    if (current.role === "admin") {
      const admins = await countAdmins(manager.companyId);
      if (admins <= 1) {
        res.status(400).json({ message: "Impossible de supprimer le dernier administrateur." });
        return;
      }
    }
    const total = await countManagers(manager.companyId);
    if (total <= 1) {
      res.status(400).json({ message: "Impossible de supprimer le dernier gestionnaire de l\u2019entreprise." });
      return;
    }
    const ok = await deleteManager(targetId);
    if (!ok) {
      res.status(404).json({ message: "Gestionnaire introuvable" });
      return;
    }
    logSecurityEvent({
      action: "manager.deleted",
      actorType: "manager",
      actorId: manager.sub,
      companyId: manager.companyId,
      metadata: { targetId, email: current.email },
      req
    });
    res.json({ ok: true });
  } catch (err) {
    console.error("[dashboard] delete manager error", err);
    res.status(500).json({ message: "Erreur serveur" });
  }
});
